<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {api} from '../api'
import {usePolling} from '../usePolling'
import {useMarketStore} from '../store'
import {time} from '../format'
import type {AssetMapping,MappingView,MarketCoin} from '../types'
import PageIntro from '../components/PageIntro.vue'
import StatCard from '../components/StatCard.vue'
import FeatureValue from '../components/FeatureValue.vue'
import Pager from '../components/Pager.vue'
const rows=ref<MappingView[]>([]);const status=ref<{catalogCount:number;catalogReceivedTime:string|null;apiKeyConfigured:boolean}|null>(null)
const route=useRoute();const store=useMarketStore();const search=ref(typeof route.query.symbol==='string'?route.query.symbol:'');const filter=ref('all');const page=ref(0);const selectedId=ref<number|null>(null)
const choices=ref<MarketCoin[]>([]);const history=ref<AssetMapping[]>([]);const query=ref('');const chosenId=ref('');const platform=ref('');const contract=ref('');const reason=ref('');const confirmed=ref(false);const editRevision=ref(0);const busy=ref(false);const actionError=ref('');const message=ref('')
async function load(signal?:AbortSignal){const [r,s]=await Promise.all([api<MappingView[]>('/api/mappings',{signal}),api<typeof status.value>('/api/mappings/status',{signal})]);rows.value=r;status.value=s;await store.refresh(signal)}
const {error,refresh}=usePolling(signal=>load(signal),10000)
const names=['Unknown','SymbolMatched','Ambiguous','ContractVerified','ManualVerified']
const filtered=computed(()=>rows.value.filter(r=>`${r.instrument.symbol} ${r.mapping?.coinGeckoId??''}`.toLowerCase().includes(search.value.trim().toLowerCase())&&(filter.value==='all'||filter.value==='trusted'&&r.capital.trustedIdentity||filter.value==='review'&&!r.capital.trustedIdentity)))
const paged=computed(()=>filtered.value.slice(page.value*30,(page.value+1)*30));watch([search,filter],()=>{page.value=0})
const selected=computed(()=>rows.value.find(r=>r.instrument.assetId===selectedId.value));const coin=computed(()=>choices.value.find(c=>c.id===chosenId.value))
const providerHealth=computed(()=>store.health.filter(h=>h.health.name.startsWith('CoinGecko')))
let editRequest=0
const lookingUp=ref(false)
async function select(row:MappingView){if(busy.value)return;const request=++editRequest;lookingUp.value=false;selectedId.value=row.instrument.assetId;query.value='';chosenId.value=row.mapping?.coinGeckoId??'';editRevision.value=row.mapping?.revision??0;platform.value=row.mapping?.platform??'';contract.value=row.mapping?.contractAddress??'';reason.value='';confirmed.value=false;actionError.value='';message.value='';choices.value=[];history.value=[];try{const [c,h]=await Promise.all([api<MarketCoin[]>(`/api/mappings/${row.instrument.assetId}/candidates`),api<AssetMapping[]>(`/api/mappings/${row.instrument.assetId}/history`)]);if(request!==editRequest)return;choices.value=c;history.value=h}catch(e){if(request===editRequest)actionError.value=String(e)}}
function chooseChanged(){platform.value='';contract.value='';confirmed.value=false}
function platformChanged(){contract.value=coin.value?.platforms[platform.value]??'';confirmed.value=false}
async function lookup(){if(busy.value||lookingUp.value)return;const request=++editRequest;lookingUp.value=true;actionError.value='';confirmed.value=false;platform.value='';contract.value='';try{const result=await api<MarketCoin[]>(`/api/coingecko/search?q=${encodeURIComponent(query.value.trim())}`);if(request!==editRequest)return;choices.value=result;if(!result.some(c=>c.id===chosenId.value))chosenId.value='';message.value=`目录匹配 ${result.length} 条，最多显示 100 条；请核对唯一 ID。`}catch(e){if(request===editRequest)actionError.value=String(e)}finally{if(request===editRequest)lookingUp.value=false}}
async function save(clear=false){if(!selected.value||busy.value)return;busy.value=true;actionError.value='';message.value='';try{const id=selected.value.instrument.assetId;const mapping=await api<AssetMapping>(`/api/mappings/${id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({coinGeckoId:clear?null:chosenId.value,expectedRevision:editRevision.value,confirmIdentity:clear?false:confirmed.value,platform:clear?null:platform.value||null,contractAddress:clear?null:contract.value||null,reason:reason.value||null})});editRevision.value=mapping.revision;confirmed.value=false;await load();history.value=await api(`/api/mappings/${id}/history`);message.value=clear?'人工映射已清除，记录已保留；后台会重新生成未确认候选。':'映射已保存；数据充足时才启用比率，市值采集按后台节流更新。'}catch(e){actionError.value=e instanceof Error?e.message:'保存失败'}finally{busy.value=false}}
</script>
<template><PageIntro eyebrow="COINGECKO · ASSET IDENTITY" title="先确认是谁，再比较规模。" description="把交易所合约、CoinGecko 唯一 ID 和链上合约分别核对。"><span class="live-pill">{{status?.catalogCount??0}} 个目录资产</span></PageIntro><p v-if="error" role="alert" class="radar-notice">{{error}} 已保留上次缓存。</p><p class="radar-notice">同名符号不等于同一资产。SymbolMatched 仅供候选参考，Ambiguous 不自动选币；只有可信身份与新鲜数据才能计算比率。市值字段目前仅展示，不改变 V2 检测评分。</p><div class="stats"><StatCard label="交易所资产" :value="rows.length" foot="本地 AssetId 保持稳定"/><StatCard label="身份可信" :value="rows.filter(r=>r.capital.trustedIdentity).length" foot="人工确认 / 合约验证"/><StatCard label="待核对" :value="rows.filter(r=>!r.capital.trustedIdentity).length" foot="不会自动提高映射置信度"/><StatCard label="有效市值样本" :value="rows.filter(r=>r.capital.marketCapUsd.status===0).length" foot="60 分钟有效窗口 · 默认 30 分钟采集"/></div><div class="provider-grid"><div v-for="h in providerHealth" :key="h.health.name" class="provider"><div><b>{{h.health.name}}</b><span class="health" :class="h.status.toLowerCase()">{{h.status}}</span></div><span>{{time(h.health.lastSuccess,true)}}</span><p v-if="h.health.error" class="provider-error">{{h.health.error}}</p></div></div><p class="refresh-text catalog-status">目录更新：{{time(status?.catalogReceivedTime)}} · {{status?.apiKeyConfigured?'已配置服务端 API Key':'使用匿名公共接口；额度受共享出口限制'}}</p><div class="section-heading"><h2>资产身份与市值</h2><button class="text-button" @click="refresh">读取最新缓存</button></div><div class="market-panel"><div class="toolbar"><label class="search"><input v-model="search" aria-label="搜索映射合约" placeholder="搜索合约或 CoinGecko ID"></label><select v-model="filter" aria-label="映射状态筛选"><option value="all">全部身份</option><option value="review">待核对</option><option value="trusted">可信身份</option></select><span class="results">{{filtered.length}} 个结果</span></div><div class="table-scroll"><table><thead><tr><th>合约</th><th>CoinGecko ID</th><th>身份状态</th><th>市值 USD</th><th>FDV USD</th><th>流通 / 总供应</th><th>OI / 市值</th><th>永续成交额 / 市值</th><th>操作</th></tr></thead><tbody><tr v-for="r in paged" :key="r.instrument.assetId"><td>{{r.instrument.symbol}}</td><td>{{r.mapping?.coinGeckoId??'Unknown'}}</td><td><span class="data-state" :class="r.capital.trustedIdentity?'valid':'warming'">{{names[r.mapping?.status??0]}}</span><small v-if="!r.capital.trustedIdentity">资产映射待确认</small></td><td><FeatureValue :feature="r.capital.marketCapUsd"/></td><td><FeatureValue :feature="r.capital.fdvUsd"/></td><td><FeatureValue :feature="r.capital.circulatingSupply"/> / <FeatureValue :feature="r.capital.totalSupply"/></td><td><FeatureValue :feature="r.capital.oiMarketCapRatio" :multiplier="100" suffix="%"/></td><td><FeatureValue :feature="r.capital.volumeMarketCapRatio" :multiplier="100" suffix="%"/></td><td><button class="text-button" @click="select(r)">核对 →</button></td></tr><tr v-if="!filtered.length"><td colspan="9" class="empty">没有符合条件的资产；后台会先加载目录并生成候选。</td></tr></tbody></table></div><Pager v-model="page" :total="filtered.length">未确认的市值仅供候选参考，不用于可信比率。</Pager></div>
<section v-if="selected" class="detail mapping-detail"><div class="section-heading"><h2>{{selected.instrument.symbol}} · 资产身份核对</h2><button class="text-button" @click="selectedId=null">收起 ×</button></div><p>{{selected.capital.mappingReason}}</p><p>AssetId {{selected.instrument.assetId}} · 当前版本 {{selected.mapping?.revision??0}} · 编辑版本 {{editRevision}} · 合约单位提示 {{selected.mapping?.contractMultiplier??1}} 倍。OI 与成交额已是美元口径，不再重复乘倍数。</p><p v-if="actionError" role="alert" class="radar-notice">{{actionError}}</p><p v-if="message" role="status" class="radar-notice">{{message}}</p><div class="toolbar mapping-search"><label class="search"><input v-model="query" aria-label="搜索 CoinGecko 目录" placeholder="输入唯一 ID、名称或符号" @keydown.enter="lookup"></label><button class="replay-action"  :disabled="busy||lookingUp" @click="lookup">搜索目录</button></div><div class="mapping-form"><label>CoinGecko 唯一 ID<select v-model="chosenId" aria-label="选择 CoinGecko ID" @change="chooseChanged"><option value="">请选择已核对的资产</option><option v-for="c in choices" :key="c.id" :value="c.id">{{c.id}} · {{c.name}} ({{c.symbol}})</option></select></label><label>链平台（可选）<select v-model="platform" aria-label="选择链平台" @change="platformChanged"><option value="">原生币 / 暂不指定链</option><option v-for="p in Object.keys(coin?.platforms??{})" :key="p" :value="p">{{p}}</option></select></label><label class="full-width">目录中的合约地址<input v-model="contract" aria-label="核对合约地址" placeholder="指定链时必须匹配该资产目录的地址" @input="confirmed=false"></label><label class="full-width">核对备注<input v-model="reason" aria-label="映射核对备注" maxlength="500" placeholder="可记录核对来源，最多 500 字"></label></div><p v-if="coin"><a :href="`https://www.coingecko.com/en/coins/${encodeURIComponent(coin.id)}`" target="_blank" rel="noopener noreferrer">打开 {{coin.name}} 的 CoinGecko 页面 ↗</a></p><label class="checkbox"><input v-model="confirmed" type="checkbox" aria-label="确认已核对资产身份">我已核对所选唯一 ID 与该交易所资产为同一身份；指定链时也已核对合约。</label><div class="mapping-actions"><button class="replay-action" :disabled="busy||lookingUp||!coin||!confirmed" @click="save(false)">{{busy?'保存中…':'保存人工确认'}}</button><button class="text-button" :disabled="busy||!selected.mapping?.coinGeckoId" @click="save(true)">清除映射</button></div><div class="detail-grid"><div><span>最大供应量</span><strong><FeatureValue :feature="selected.capital.maxSupply"/></strong></div><div><span>历史最高价 USD</span><strong><FeatureValue :feature="selected.capital.athUsd"/></strong></div><div><span>CoinGecko 现货汇总成交额</span><strong><FeatureValue :feature="selected.capital.volume24hUsd"/></strong></div><div><span>Binance 永续成交额 / 市值</span><strong><FeatureValue :feature="selected.capital.volumeMarketCapRatio" :multiplier="100" suffix="%"/></strong></div></div><div class="section-heading radar-heading"><h2>映射修改记录</h2></div><div class="table-scroll"><table><thead><tr><th>版本</th><th>时间</th><th>ID / 状态</th><th>链 / 合约</th><th>依据</th></tr></thead><tbody><tr v-for="h in history" :key="h.revision"><td>{{h.revision}}</td><td>{{time(h.updatedAt)}}</td><td>{{h.coinGeckoId??'Unknown'}} · {{names[h.status]}}</td><td>{{h.platform??'—'}} / {{h.contractAddress??'—'}}</td><td class="decision-reason">{{h.reason}}</td></tr><tr v-if="!history.length"><td colspan="5" class="empty">尚无已保存的映射记录。</td></tr></tbody></table></div></section></template>
